#ifndef LUGALOS_DRIVERS_ICONS_H
#define LUGALOS_DRIVERS_ICONS_H

#include <stdbool.h>
#include <stdint.h>

#include "drivers/ugui.h"

/* Icons (drivers/icons.c).
 *
 * An icon is 4-bit gray, two pixels a byte (the left one in the high
 * nibble), rows padded to a byte: 0 ink .. 14 white, 15 transparent. Each
 * comes at 64 x 64 and 32 x 32; drawn at a scale's multiple of either.
 *
 * The built-in set is generated by tools/gen_icons.py from
 * assets/icons/*.png into drivers/icons_data.c (.rodata, sorted by name).
 *
 * On a card an icon is a .GIC file: "GIC1", u16 width, u16 height (little
 * endian), u8 bits per pixel (4), three zero bytes, then the pixels as
 * above. /sd0/system/icons/NAME.GIC (64 x 64) is where 71.4's resolver
 * looks after the built-ins. */

#define ICON_CLEAR 15u

typedef struct {
    const char    *name;
    const uint8_t *px32;        /* 32 x 32: 512 bytes */
    const uint8_t *px64;        /* 64 x 64: 2048 bytes */
} icon_t;

/* The built-in icon called name, or NULL. */
const icon_t *icon_find(const char *name);

/* The built-in icon called name, or the one called fallback ("app", "doc",
 * ...), or NULL. */
const icon_t *icon_or(const char *name, const char *fallback);

/* An icon as an image of size x size (32 or 64 per scale step): the larger
 * form at size >= 64, scaled by size / 64; the 32 one otherwise. */
ugui_image_t icon_image(const icon_t *icon, int size, int *scale);

/* The built-in icons in name order: i from 0 until NULL. */
const icon_t *icon_at(unsigned i);

/* `icons check`: sorted, every image present. Returns the faults. */
int icons_check(void);

#endif /* LUGALOS_DRIVERS_ICONS_H */
